CREATE TABLE IF NOT EXISTS billing_payments (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id VARCHAR(255) NOT NULL REFERENCES user_profiles(auth_subject) ON DELETE CASCADE, plan_key VARCHAR(50) NOT NULL, billing_cycle VARCHAR(20) NOT NULL, payment_method VARCHAR(30) NOT NULL CHECK (payment_method IN ('payfast','bank_transfer')), status VARCHAR(30) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','awaiting_review','paid','failed','cancelled','rejected')), amount_cents INTEGER NOT NULL CHECK (amount_cents > 0), reference VARCHAR(120) NOT NULL UNIQUE, gateway_payment_id VARCHAR(120), proof_note TEXT, raw_payload JSONB NOT NULL DEFAULT '{}'::jsonb, paid_at TIMESTAMP WITH TIME ZONE, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS billing_payments_user_idx ON billing_payments(user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS billing_payments_status_idx ON billing_payments(status, created_at DESC);
